<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';$user=require_login();ensure_customer_workspace_schema();if(!in_array($user['role'],['admin','manager'],true)){http_response_code(403);exit('Η πρόσβαση επιτρέπεται μόνο στη διοίκηση.');}
$query=trim(mb_substr((string)($_GET['q']??''),0,120));$status=(string)($_GET['status']??'');$statusLabels=['draft'=>'Draft - internal','verified'=>'Verified - internal','shareable'=>'Client Shareable'];$where=[];$params=[];if($query!==''){$where[]='(p.profile_id LIKE ? OR p.internal_name LIKE ? OR p.primary_role LIKE ? OR c.name LIKE ?)';$n='%'.$query.'%';array_push($params,$n,$n,$n,$n);}if(array_key_exists($status,$statusLabels)){$where[]='p.profile_status=?';$params[]=$status;}$sql='SELECT p.*,c.name AS company_name,c.legal_name AS company_legal_name FROM engineering_profiles p LEFT JOIN companies c ON c.id=p.company_id AND c.deleted_at IS NULL'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY p.updated_at DESC';$s=db()->prepare($sql);$s->execute($params);$profiles=$s->fetchAll();render_header('Client-specific Packs',$user);
?>
<div class="page-heading"><div><p class="eyebrow">CLIENT-SPECIFIC PACKS</p><h1>Engineering Profiles</h1><p>Επαληθευμένα client-facing profiles, οργανωμένα προαιρετικά ανά πελάτη και χωρίς προσωπικά στοιχεία επικοινωνίας.</p></div><div class="actions"><a class="button" href="<?= e(crm_url('corporate-documents.php')) ?>">Εταιρικά έντυπα</a><a class="button primary" href="<?= e(crm_url('profile.php')) ?>">+ Νέο profile</a></div></div><section class="card toolbar-card"><form method="get" class="filters"><label>Αναζήτηση<input name="q" value="<?= e($query) ?>" placeholder="Profile ID, engineer, role ή πελάτης"></label><label>Κατάσταση<select name="status"><option value="">Όλες</option><?php foreach($statusLabels as$v=>$label): ?><option value="<?= e($v) ?>" <?= $status===$v?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></label><button class="button primary">Εφαρμογή</button><a class="button" href="<?= e(crm_url('profiles.php')) ?>">Καθαρισμός</a></form></section><section class="card table-card"><?php if(!$profiles): ?><div class="empty-state"><h2>Δεν υπάρχουν profiles</h2><p>Δημιουργήστε το πρώτο Engineering Profile.</p><a class="button primary" href="<?= e(crm_url('profile.php')) ?>">Νέο profile</a></div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Profile</th><th>Πελάτης</th><th>Internal engineer</th><th>Role / Seniority</th><th>Κατάσταση</th><th>Ενημέρωση</th><th></th></tr></thead><tbody><?php foreach($profiles as$row): ?><tr><td><strong><?= e($row['profile_id']) ?></strong></td><td><?= e($row['company_legal_name']?:($row['company_name']?:'Γενικό profile')) ?></td><td><?= e($row['internal_name']) ?></td><td><?= e($row['primary_role']) ?><small><?= e($row['seniority']) ?></small></td><td><span class="proposal-status proposal-status-<?= e($row['profile_status']) ?>"><?= e($statusLabels[$row['profile_status']]??$row['profile_status']) ?></span></td><td><?= e(format_datetime($row['updated_at'])) ?></td><td class="table-actions"><a class="button small" href="<?= e(crm_url('profile.php?id='.urlencode((string)$row['id']))) ?>">Άνοιγμα</a><a class="button small" target="_blank" href="<?= e(crm_url('profile-view.php?id='.urlencode((string)$row['id']))) ?>">Προβολή</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section><?php render_footer(); ?>
